<?php
require_once __DIR__ . '/_layout.php';requirePermission('contracts.manage');$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$quotes=dbFetchAll("SELECT r.reference,r.id,r.created_at,c.first_name,c.last_name,r.total_amount,r.currency FROM reservations r JOIN customers c ON c.id=r.customer_id WHERE r.agency_id IN ($ph) AND r.status='quote' ORDER BY r.created_at DESC",$ids);$contracts=dbFetchAll("SELECT rc.id,rc.contract_number,rc.status,rc.current_version,c.first_name,c.last_name FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id JOIN customers c ON c.id=r.customer_id WHERE r.agency_id IN ($ph) ORDER BY rc.created_at DESC",$ids);$invoices=dbFetchAll("SELECT i.id,i.invoice_number,i.status,i.total_amount,i.currency,c.first_name,c.last_name FROM invoices i JOIN customers c ON c.id=i.customer_id WHERE i.agency_id IN ($ph) ORDER BY i.issued_at DESC",$ids);backofficeHeader('Documents','documents.php');?><div class="page-head"><h1>Quotes, contracts, and invoices</h1></div><div class="grid"><section class="card"><h2>Quotes</h2><div class="table-wrap"><table><tr><th>Reference</th><th>Customer</th><th>Total</th><th>Document</th></tr><?php foreach($quotes as $q):?><tr><td><?=e($q['reference'])?></td><td><?=e($q['first_name'].' '.$q['last_name'])?></td><td><?=money($q['total_amount'],$q['currency'])?></td><td><a class="btn secondary" target="_blank" href="quote_print.php?id=<?=e($q['id'])?>">Print / PDF</a></td></tr><?php endforeach;?></table></div></section><section class="card"><h2>Contracts</h2><div class="table-wrap"><table><tr><th>Number</th><th>Customer</th><th>Status</th><th>Version</th><th>Document</th></tr><?php foreach($contracts as $c):?><tr><td><?=e($c['contract_number'])?></td><td><?=e($c['first_name'].' '.$c['last_name'])?></td><td><?=statusBadge($c['status'])?></td><td><?=e($c['current_version'])?></td><td><a class="btn secondary" target="_blank" href="contract_print.php?id=<?=e($c['id'])?>&lang=fr">Print / PDF</a></td></tr><?php endforeach;?></table></div></section></div><section class="card" style="margin-top:1rem"><h2>Invoices</h2><div class="table-wrap"><table><tr><th>Number</th><th>Customer</th><th>Total</th><th>Status</th><th>Document</th></tr><?php foreach($invoices as $i):?><tr><td><?=e($i['invoice_number'])?></td><td><?=e($i['first_name'].' '.$i['last_name'])?></td><td><?=money($i['total_amount'],$i['currency'])?></td><td><?=statusBadge($i['status'])?></td><td><a class="btn secondary" target="_blank" href="invoice_print.php?id=<?=e($i['id'])?>">Print / PDF</a></td></tr><?php endforeach;?></table></div></section><?php backofficeFooter();

